size(180);
currentprojection = perspective(6,3,2);

triple I = (1,0,0), J = (0,1,0), K = (0,0,1);
triple O = (0,-0.2,0), A = (2*dir(110)), B = (2*dir(230)), C = (2*sqrt(39)/8*(A + B) + 2*sqrt(15)/8*cross(A,B)), D = (A + B)/2, E = (cross(A,B))/sqrt(39);

draw(B--B + 2.2*(A - B),dashed,Arrow3(6));
draw(B--B + 2.2*(C - B),dashed,Arrow3(6));
draw(O--A,Arrow3(6));
