draw(B--B + C - O--C);
draw(O--C + 0.8*(cross(A,B)),magenta,Arrow3(6));
draw(O--D,green,Arrow3(6));
draw(O--2*E,blue,Arrow3(6));

label("$\mathbf{a}$", A, N);
label("$\mathbf{b}$", B, SW);
label("$\mathbf{c}$", C, E);
label("$\mathbf{a} \times \mathbf{b}$", C + 0.8*(cross(A,B)), S);
label("$\mathbf{d}$", D, S);
label("$\mathbf{e}$", 2*E, dir(0));
